import{_ as l,c as e,o as i,ag as t}from"./chunks/framework.B1jFR3yW.js";const u=JSON.parse('{"title":"008 特征降维","description":"","frontmatter":{},"headers":[],"relativePath":"python/机器学习/008特征降维.md","filePath":"python/机器学习/008特征降维.md"}'),r={name:"python/机器学习/008特征降维.md"};function o(h,a,n,c,d,p){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="_008-特征降维" tabindex="-1">008 特征降维 <a class="header-anchor" href="#_008-特征降维" aria-label="Permalink to &quot;008 特征降维&quot;">​</a></h1><h2 id="什么是特征降维" tabindex="-1">什么是特征降维 <a class="header-anchor" href="#什么是特征降维" aria-label="Permalink to &quot;什么是特征降维&quot;">​</a></h2><p>特征降维就是把高维数据压缩到更低维，同时尽量保留主要信息。</p><h2 id="为什么需要降维" tabindex="-1">为什么需要降维 <a class="header-anchor" href="#为什么需要降维" aria-label="Permalink to &quot;为什么需要降维&quot;">​</a></h2><p>常见原因：</p><ul><li>特征太多，训练成本高</li><li>特征之间存在冗余</li><li>数据中有噪声</li><li>想做二维或三维可视化</li></ul><h2 id="pca-是什么" tabindex="-1">PCA 是什么 <a class="header-anchor" href="#pca-是什么" aria-label="Permalink to &quot;PCA 是什么&quot;">​</a></h2><p>PCA 是课程里最常见的降维方法。</p><p>它会寻找数据中“变化最明显”的方向，把原始数据投影到这些方向上。</p><h2 id="pca-的作用" tabindex="-1">PCA 的作用 <a class="header-anchor" href="#pca-的作用" aria-label="Permalink to &quot;PCA 的作用&quot;">​</a></h2><ul><li>压缩特征</li><li>去噪</li><li>提升训练效率</li><li>辅助可视化</li></ul><h2 id="pca-的代价" tabindex="-1">PCA 的代价 <a class="header-anchor" href="#pca-的代价" aria-label="Permalink to &quot;PCA 的代价&quot;">​</a></h2><p>降维后通常会损失一部分信息，而且新特征往往失去原始业务含义，可解释性会下降。</p><h2 id="什么时候适合试降维" tabindex="-1">什么时候适合试降维 <a class="header-anchor" href="#什么时候适合试降维" aria-label="Permalink to &quot;什么时候适合试降维&quot;">​</a></h2><p>当你遇到这些情况时，可以考虑降维：</p><ul><li>特征维度过高</li><li>模型训练太慢</li><li>多个特征明显高度相关</li><li>想把高维数据投影到二维平面观察结构</li></ul><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><p>这一篇要掌握的重点是：</p><ul><li>降维不是随便删特征</li><li>PCA 更像是“重新构造更少的新特征”</li><li>它适合压缩、去噪和可视化</li></ul>',19)])])}const _=l(r,[["render",o]]);export{u as __pageData,_ as default};
